import { type FormEvent, type ReactNode, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import {
  ArrowLeft, ArrowUpRight, Bell, Check, CircleAlert, CircleCheck,
  ClipboardList, Clock3, Compass, FileText, Filter, Heart, Home, LayoutDashboard,
  Loader2, LockKeyhole, MapPinned, Menu, Minus, Plus,
  Search, Send, ShieldCheck, Sparkles, Target, TrendingUp, Upload,
  UserRound, UsersRound, X, Zap,
} from 'lucide-react';
import {
  getGetAdminOverviewQueryKey, getGetDashboardQueryKey, getListReportsQueryKey, useCreateReport, useGetAdminOverview,
  useGetDashboard, useGetStats, useListCategories, useListReports, useRequestUploadUrl, useSupportReport,
  useUpdateReport,
} from '@workspace/api-client-react';
import type { AdminOverview, Category, Report, ReportInput } from '@workspace/api-client-react';
import { Link, Route, Switch, Router as WouterRouter, useLocation } from 'wouter';
import logo from './logo.jpeg';

const queryClient = new QueryClient();
const statuses = [
  { id: 'all', label: 'كل الحالات' }, { id: 'received', label: 'استلمناها' },
  { id: 'reviewing', label: 'قيد المراجعة' }, { id: 'referred', label: 'أُحيلت' },
  { id: 'resolved', label: 'تم الحل' }, { id: 'closed', label: 'مغلقة' },
];
const fallbackCategories = [
  { id: 'cleanliness', name: 'cleanliness', label: 'نظافة المكان', icon: '01' },
  { id: 'roads', name: 'roads', label: 'طرق وأرصفة', icon: '02' },
  { id: 'lighting', name: 'lighting', label: 'إنارة', icon: '03' },
  { id: 'landscaping', name: 'landscaping', label: 'تشجير وتجميل', icon: '04' },
];

function cn(...values: Array<string | false | null | undefined>) { return values.filter(Boolean).join(' '); }
function fmtDate(date?: string) {
  if (!date) return 'منذ قليل';
  return new Intl.DateTimeFormat('ar-KW', { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(date));
}
function statusTone(status: string) {
  return status === 'resolved' || status === 'closed' ? 'bg-[#e2efd4] text-[#397047]' : status === 'reviewing' || status === 'referred' ? 'bg-[#fff0cc] text-[#87611c]' : 'bg-[#e8efee] text-[#2e6258]';
}
function statusIcon(status: string) {
  return status === 'resolved' || status === 'closed' ? <CircleCheck className="size-3.5" /> : status === 'reviewing' ? <Clock3 className="size-3.5" /> : <CircleAlert className="size-3.5" />;
}

function Shell({ children }: { children: ReactNode }) {
  const [location] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const nav = [
    { href: '/', label: 'الرئيسية', icon: Home },
    { href: '/reports', label: 'بلاغات المجتمع', icon: ClipboardList },
    { href: '/dashboard', label: 'مساحتي', icon: LayoutDashboard },
  ];
  return (
    <div className="min-h-[100dvh] bg-background">
      <header className="sticky top-0 z-40 border-b border-border/70 bg-background/90 backdrop-blur-xl">
        <div className="mx-auto flex h-[72px] max-w-[1440px] items-center justify-between px-4 sm:px-8">
          <div className="flex items-center gap-4">
            <button data-testid="button-mobile-menu" className="rounded-xl p-2 hover:bg-muted md:hidden" onClick={() => setMobileOpen(!mobileOpen)} aria-label="فتح القائمة"><Menu className="size-5" /></button>
            <Link href="/" data-testid="link-brand" className="flex items-center gap-3">
              <img src={logo} alt="نجمّلها" className="h-11 w-[78px] rounded-lg object-cover object-center mix-blend-multiply" />
              <span className="hidden border-r border-border pr-3 text-xs font-medium text-muted-foreground sm:block">معاً نخليها أجمل</span>
            </Link>
          </div>
          <nav className="hidden items-center gap-1 md:flex">
            {nav.map(({ href, label, icon: Icon }) => <Link key={href} href={href} data-testid={`link-nav-${label}`} className={cn('flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-medium transition-colors', location === href ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-muted hover:text-foreground')}><Icon className="size-4" />{label}</Link>)}
          </nav>
          <div className="flex items-center gap-2">
            <Link href="/report/new" data-testid="link-header-report" className="hidden items-center gap-2 rounded-xl bg-accent px-4 py-2.5 text-sm font-semibold text-accent-foreground shadow-sm transition-transform hover:-translate-y-0.5 sm:flex"><Plus className="size-4" />أضف بلاغاً</Link>
            <Link href="/login" data-testid="link-header-login" className="flex size-10 items-center justify-center rounded-xl border border-border bg-card text-primary hover:bg-muted"><UserRound className="size-[18px]" /></Link>
          </div>
        </div>
        {mobileOpen && <div className="border-t border-border bg-card px-4 py-3 md:hidden">{nav.map(({ href, label, icon: Icon }) => <Link onClick={() => setMobileOpen(false)} key={href} href={href} data-testid={`link-mobile-${label}`} className={cn('flex items-center gap-3 rounded-xl px-3 py-3 text-sm', location === href ? 'bg-primary text-primary-foreground' : 'text-muted-foreground')}><Icon className="size-4" />{label}</Link>)}</div>}
      </header>
      <main>{children}</main>
      <footer className="mt-16 border-t border-border/80 bg-primary text-primary-foreground">
        <div className="mx-auto flex max-w-[1440px] flex-col gap-5 px-4 py-8 sm:flex-row sm:items-center sm:justify-between sm:px-8">
          <div><div className="mb-1 flex items-center gap-2"><img src={logo} alt="" className="h-8 w-14 rounded object-cover object-center mix-blend-screen opacity-90" /><span className="font-semibold">نجمّلها</span></div><p className="text-xs text-primary-foreground/60">من الكويت، للكويت.</p></div>
          <div className="flex gap-5 text-xs text-primary-foreground/65"><Link href="/reports" data-testid="link-footer-reports">البلاغات</Link><Link href="/login" data-testid="link-footer-login">تسجيل الدخول</Link></div>
        </div>
      </footer>
    </div>
  );
}

function AsyncState({ type, retry }: { type: 'loading' | 'error' | 'empty'; retry?: () => void }) {
  if (type === 'loading') return <div className="grid gap-4 sm:grid-cols-2"><div className="h-48 animate-pulse rounded-2xl bg-muted" /><div className="h-48 animate-pulse rounded-2xl bg-muted" /></div>;
  if (type === 'empty') return <div className="rounded-3xl border border-dashed border-border bg-card px-6 py-16 text-center"><div className="mx-auto mb-4 flex size-14 items-center justify-center rounded-2xl bg-secondary/35 text-primary"><Compass className="size-7" /></div><h3 className="font-semibold">ما في بلاغات بهذا الوصف</h3><p className="mt-2 text-sm text-muted-foreground">جرّب تغيير الفلاتر أو كن أول من يشارك ملاحظته.</p><Link href="/report/new" data-testid="link-empty-report" className="mt-5 inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground">أضف بلاغاً <ArrowLeft className="size-4" /></Link></div>;
  return <div className="rounded-3xl border border-border bg-card px-6 py-14 text-center"><CircleAlert className="mx-auto mb-3 size-8 text-accent" /><h3 className="font-semibold">تعذر تحميل البيانات</h3><p className="mt-2 text-sm text-muted-foreground">تحقق من الاتصال وحاول مرة أخرى.</p>{retry && <button data-testid="button-retry" onClick={retry} className="mt-5 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground">إعادة المحاولة</button>}</div>;
}

function StatChip({ value, label, accent = false }: { value: string | number; label: string; accent?: boolean }) {
  return <div className={cn('rounded-2xl border px-4 py-3', accent ? 'border-secondary/30 bg-secondary/20' : 'border-border bg-card')}><div className="font-mono-civic text-xl font-bold tracking-tight">{value}</div><div className="mt-1 text-xs text-muted-foreground">{label}</div></div>;
}

function ReportCard({ report, onSelect, onSupport }: { report: Report; onSelect: (report: Report) => void; onSupport?: (id: number) => void }) {
  return <article data-testid={`card-report-${report.id}`} className="group overflow-hidden rounded-3xl border border-border bg-card shadow-xs transition-all hover:-translate-y-1 hover:shadow-md">
    <button data-testid={`button-open-report-${report.id}`} onClick={() => onSelect(report)} className="block w-full text-right">
      <div className="relative h-40 overflow-hidden bg-muted">{report.image ? <img src={report.image} alt={report.title} className="h-full w-full object-cover transition-transform duration-500 group-hover:scale-105" /> : <div className="civic-grid flex h-full items-center justify-center text-primary/30"><MapPinned className="size-10" /></div>}<span className={cn('absolute right-3 top-3 flex items-center gap-1 rounded-full px-2.5 py-1 text-[11px] font-semibold', statusTone(report.status))}>{statusIcon(report.status)}{report.statusLabel}</span></div>
      <div className="p-5"><div className="mb-2 flex items-center justify-between gap-3"><span className="text-xs text-muted-foreground">{report.categoryLabel}</span><span className="font-mono-civic text-[10px] text-muted-foreground">#{String(report.id).padStart(4, '0')}</span></div><h3 className="line-clamp-1 font-semibold">{report.title}</h3><p className="mt-2 line-clamp-2 text-sm leading-6 text-muted-foreground">{report.description}</p><div className="mt-4 flex items-center justify-between border-t border-border/70 pt-3 text-xs text-muted-foreground"><span className="flex items-center gap-1"><MapPinned className="size-3.5" />{report.locationName}</span><span>{fmtDate(report.createdAt)}</span></div></div>
    </button>
    <div className="flex items-center justify-between border-t border-border/70 px-5 py-3"><span className="flex items-center gap-1 text-xs font-semibold text-secondary-foreground"><Zap className="size-3.5" />+{report.points} نقطة</span><button data-testid={`button-support-${report.id}`} onClick={() => onSupport?.(report.id)} className="flex items-center gap-1.5 rounded-lg px-2 py-1 text-xs text-muted-foreground transition-colors hover:bg-accent/10 hover:text-accent"><Heart className="size-3.5" />دعم البلاغ <span className="font-mono-civic">{report.supportCount}</span></button></div>
  </article>;
}

function ReportModal({ report, close, support }: { report: Report; close: () => void; support: (id: number) => void }) {
  return <div className="fixed inset-0 z-50 flex items-center justify-center bg-primary/35 p-4 backdrop-blur-sm" role="dialog" aria-modal="true"><div className="max-h-[90dvh] w-full max-w-lg overflow-auto rounded-3xl border border-border bg-card shadow-2xl animate-rise"><div className="relative h-52 bg-muted">{report.image && <img src={report.image} alt={report.title} className="h-full w-full object-cover" />}<button data-testid="button-close-report-modal" onClick={close} className="absolute left-4 top-4 rounded-full bg-card/90 p-2 text-primary shadow-sm"><X className="size-4" /></button></div><div className="p-6"><div className="flex items-center justify-between"><span className={cn('flex items-center gap-1 rounded-full px-3 py-1 text-xs font-semibold', statusTone(report.status))}>{statusIcon(report.status)}{report.statusLabel}</span><span className="font-mono-civic text-xs text-muted-foreground">#{report.id}</span></div><h2 className="mt-4 text-xl font-bold">{report.title}</h2><p className="mt-3 text-sm leading-7 text-muted-foreground">{report.description}</p><div className="mt-5 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-muted/70 p-3"><div className="text-xs text-muted-foreground">الموقع</div><div className="mt-1 text-sm font-semibold">{report.locationName}</div></div><div className="rounded-2xl bg-muted/70 p-3"><div className="text-xs text-muted-foreground">المساهم</div><div className="mt-1 text-sm font-semibold">{report.authorName || 'من أهل الديرة'}</div></div></div><div className="mt-6 flex items-center justify-between"><span className="flex items-center gap-1 text-sm font-semibold text-secondary-foreground"><Zap className="size-4" />+{report.points} نقطة للمساهمة</span><button data-testid={`button-modal-support-${report.id}`} onClick={() => support(report.id)} className="flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground"><Heart className="size-4" />أدعم البلاغ</button></div></div></div></div>;
}

function HomePage() {
  const statsQuery = useGetStats();
  const reportsQuery = useListReports({ sort: 'latest' }, { query: { queryKey: getListReportsQueryKey({ sort: 'latest' }), staleTime: 60_000 } });
  const stats = statsQuery.data;
  const reports = reportsQuery.data || [];
  const [selected, setSelected] = useState<Report | null>(null);
  const support = useSupportReport();
  const qc = useQueryClient();
  const doSupport = (id: number) => support.mutate({ id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListReportsQueryKey({ sort: 'latest' }) }); setSelected(null); } });
  return <div>
    <section className="relative overflow-hidden border-b border-border/70">
      <div className="absolute inset-0 civic-grid opacity-70" /><div className="absolute -left-24 top-16 size-72 rounded-full bg-secondary/20 blur-3xl" />
      <div className="relative mx-auto grid max-w-[1440px] items-center gap-12 px-4 py-16 sm:px-8 lg:grid-cols-[1.1fr_.9fr] lg:py-24">
        <div className="animate-rise"><div className="mb-6 inline-flex items-center gap-2 rounded-full border border-primary/15 bg-card/70 px-3 py-1.5 text-xs font-semibold text-primary"><span className="size-2 rounded-full bg-secondary" />حركة مجتمعية من الكويت</div><h1 className="display-ar max-w-3xl text-5xl font-bold leading-[1.15] sm:text-7xl">نجمّلها،<br /><span className="text-accent">شارعاً شارعاً.</span></h1><p className="mt-6 max-w-xl text-base leading-8 text-muted-foreground sm:text-lg">منصة تجمع ملاحظات أهل الكويت، وتحوّلها إلى خطوات واضحة. صوّر المشكلة، تابع حلّها، وخذ دورك في جعل المكان أجمل.</p><div className="mt-8 flex flex-wrap gap-3"><Link href="/report/new" data-testid="link-hero-report" className="flex items-center gap-2 rounded-xl bg-primary px-5 py-3.5 text-sm font-semibold text-primary-foreground shadow-md transition-transform hover:-translate-y-0.5">شارك بملاحظة <ArrowLeft className="size-4" /></Link><Link href="/reports" data-testid="link-hero-reports" className="flex items-center gap-2 rounded-xl border border-border bg-card px-5 py-3.5 text-sm font-semibold text-primary hover:bg-muted">تصفح البلاغات <ClipboardList className="size-4" /></Link></div></div>
        <div className="relative mx-auto w-full max-w-[500px] animate-rise delay-2"><div className="absolute -inset-5 rounded-[2.5rem] border border-primary/10" /><div className="relative overflow-hidden rounded-[2rem] border border-border bg-primary p-5 shadow-xl"><div className="absolute right-0 top-0 h-2 w-full bg-accent" /><div className="absolute right-0 top-2 h-2 w-full bg-card" /><div className="absolute right-0 top-4 h-2 w-full bg-secondary" /><div className="mt-8 rounded-2xl bg-[#d4e1d4]/10 p-4"><div className="flex items-center justify-between text-primary-foreground/70"><span className="text-xs">أثر المجتمع اليوم</span><TrendingUp className="size-4 text-secondary" /></div><div className="mt-5 font-mono-civic text-6xl font-bold text-secondary">{stats?.communityContributions ?? 1284}</div><div className="mt-2 text-sm text-primary-foreground/70">مساهمة صنعت فرقاً في أحياء الكويت</div></div><div className="mt-3 grid grid-cols-2 gap-3"><div className="rounded-2xl bg-primary-foreground/10 p-4"><div className="font-mono-civic text-2xl font-bold text-primary-foreground">{stats?.resolvedReports ?? 347}</div><div className="mt-1 text-xs text-primary-foreground/60">بلاغ تم حله</div></div><div className="rounded-2xl bg-secondary p-4 text-primary"><div className="font-mono-civic text-2xl font-bold">{stats?.activeAreas ?? 18}</div><div className="mt-1 text-xs opacity-70">منطقة نشطة</div></div></div><div className="mt-6 flex items-center justify-between rounded-2xl border border-primary-foreground/10 px-4 py-3 text-xs text-primary-foreground/70"><span className="flex items-center gap-2"><ShieldCheck className="size-4 text-secondary" />كل ملاحظة لها أثر</span><ArrowUpRight className="size-4" /></div></div></div>
      </div>
    </section>
    <section className="mx-auto max-w-[1440px] px-4 py-14 sm:px-8"><div className="grid gap-3 sm:grid-cols-4"><StatChip value={stats?.totalReports ?? '—'} label="بلاغ من المجتمع" /><StatChip value={stats?.resolvedReports ?? '—'} label="تم حلّه" accent /><StatChip value={stats?.communityContributions ?? '—'} label="مساهمة مجتمعية" /><StatChip value={stats?.activeAreas ?? '—'} label="منطقة نشطة" /></div></section>
    <section className="mx-auto max-w-[1440px] px-4 pb-16 sm:px-8"><div className="mb-6 flex items-end justify-between"><div><span className="text-xs font-semibold text-accent">نبض المدينة</span><h2 className="mt-2 text-2xl font-bold">آخر ما شاركه أهل الكويت</h2></div><Link href="/reports" data-testid="link-home-all-reports" className="flex items-center gap-1 text-sm font-semibold text-primary">كل البلاغات <ArrowLeft className="size-4" /></Link></div>{reportsQuery.isLoading ? <AsyncState type="loading" /> : reportsQuery.isError ? <AsyncState type="error" retry={() => reportsQuery.refetch()} /> : reports.length === 0 ? <AsyncState type="empty" /> : <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">{reports.slice(0, 3).map((report) => <ReportCard key={report.id} report={report} onSelect={setSelected} onSupport={doSupport} />)}</div>}</section>
    <section className="mx-auto max-w-[1440px] px-4 pb-20 sm:px-8"><div className="relative overflow-hidden rounded-[2rem] bg-secondary px-6 py-10 sm:px-12"><div className="absolute -left-10 -top-20 size-64 rounded-full border-[30px] border-primary/10" /><div className="relative max-w-2xl"><Sparkles className="mb-5 size-6 text-primary" /><h2 className="text-3xl font-bold text-primary">المكان لنا كلنا.</h2><p className="mt-3 leading-8 text-primary/75">بلاغ واحد قد يلفت الانتباه، ودعم واحد قد يسرّع الحل. نجمّلها مساحة صغيرة لفعل كبير.</p><Link href="/report/new" data-testid="link-home-cta" className="mt-6 inline-flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground">ابدأ مساهمتك <ArrowLeft className="size-4" /></Link></div></div></section>
    {selected && <ReportModal report={selected} close={() => setSelected(null)} support={doSupport} />}
  </div>;
}

function ReportsPage() {
  const [search, setSearch] = useState(''); const [status, setStatus] = useState('all'); const [category, setCategory] = useState('all'); const [selected, setSelected] = useState<Report | null>(null);
  const categoriesQuery = useListCategories(); const cats: Category[] = (categoriesQuery.data || fallbackCategories).map((cat) => ({ ...cat, name: cat.id }));
  const params = useMemo(() => ({ ...(search.trim() ? { search: search.trim() } : {}), ...(status !== 'all' ? { status: status as 'received' } : {}), ...(category !== 'all' ? { category } : {}), sort: 'latest' as const }), [search, status, category]);
  const reportsQuery = useListReports(params, { query: { queryKey: getListReportsQueryKey(params), staleTime: 30_000 } }); const reports = reportsQuery.data || [];
  const support = useSupportReport(); const qc = useQueryClient();
  const doSupport = (id: number) => support.mutate({ id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListReportsQueryKey(params) }); setSelected(null); } });
  return <PageFrame eyebrow="بلاغات المجتمع" title="ملاحظات تصنع فرقاً" description="تصفح ما لاحظه أهل الكويت، وتابع رحلة كل بلاغ من الاستلام إلى الحل."><div className="rounded-3xl border border-border bg-card p-3 shadow-xs"><div className="flex flex-col gap-3 lg:flex-row"><label className="relative flex-1"><Search className="absolute right-4 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" /><input data-testid="input-search-reports" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="ابحث باسم المكان أو البلاغ..." className="h-12 w-full rounded-xl border-0 bg-muted/70 pr-11 text-sm outline-none ring-0 placeholder:text-muted-foreground focus:bg-muted" /></label><div className="flex gap-2 overflow-auto">{statuses.map((item) => <button data-testid={`button-filter-status-${item.id}`} key={item.id} onClick={() => setStatus(item.id)} className={cn('whitespace-nowrap rounded-xl px-3.5 py-2 text-xs font-semibold transition-colors', status === item.id ? 'bg-primary text-primary-foreground' : 'bg-muted/70 text-muted-foreground hover:text-foreground')}>{item.label}</button>)}</div></div><div className="mt-3 flex items-center gap-2 overflow-auto border-t border-border/60 pt-3"><Filter className="size-4 shrink-0 text-muted-foreground" /><button data-testid="button-filter-category-all" onClick={() => setCategory('all')} className={cn('whitespace-nowrap rounded-lg px-3 py-1.5 text-xs', category === 'all' ? 'bg-secondary text-primary' : 'text-muted-foreground hover:bg-muted')}>كل التصنيفات</button>{cats.map((cat) => <button data-testid={`button-filter-category-${cat.id}`} key={cat.id} onClick={() => setCategory(cat.name)} className={cn('whitespace-nowrap rounded-lg px-3 py-1.5 text-xs', category === cat.name ? 'bg-secondary text-primary' : 'text-muted-foreground hover:bg-muted')}>{cat.label}</button>)}</div></div><div className="mb-5 mt-8 flex items-center justify-between"><p className="text-sm text-muted-foreground">{reportsQuery.isLoading ? 'جارٍ التحديث...' : `${reports.length} بلاغ ظاهر`}</p><Link href="/report/new" data-testid="link-reports-add" className="flex items-center gap-2 rounded-xl bg-accent px-4 py-2.5 text-xs font-semibold text-accent-foreground"><Plus className="size-4" />أضف بلاغاً</Link></div>{reportsQuery.isLoading ? <AsyncState type="loading" /> : reportsQuery.isError ? <AsyncState type="error" retry={() => reportsQuery.refetch()} /> : reports.length === 0 ? <AsyncState type="empty" /> : <div className="grid gap-5 md:grid-cols-2 xl:grid-cols-3">{reports.map((report) => <ReportCard key={report.id} report={report} onSelect={setSelected} onSupport={doSupport} />)}</div>}{selected && <ReportModal report={selected} close={() => setSelected(null)} support={doSupport} />}</PageFrame>;
}

function MapPage() {
  const [status, setStatus] = useState('all'); const [selected, setSelected] = useState<Report | null>(null); const reportsQuery = useListReports(status === 'all' ? {} : { status: status as 'received' }, { query: { queryKey: getListReportsQueryKey(status === 'all' ? {} : { status: status as 'received' }) } }); const reports = reportsQuery.data || [];
  const support = useSupportReport(); const qc = useQueryClient();
  const positions = (r: Report, i: number) => ({ left: `${Math.min(89, Math.max(10, ((r.longitude - 46.55) / 1.65) * 100))}%`, top: `${Math.min(78, Math.max(13, ((30.1 - r.latitude) / 1.25) * 100 + (i % 2) * 3))}%` });
  return <PageFrame eyebrow="خريطة الكويت" title="كل ملاحظة على الخريطة" description="شوف الصورة الأكبر: أين تتركز الملاحظات؟ وما الذي يتحسن حولك؟"><div className="mb-5 flex items-center gap-2 overflow-auto">{statuses.slice(0, 5).map((item) => <button data-testid={`button-map-filter-${item.id}`} key={item.id} onClick={() => setStatus(item.id)} className={cn('whitespace-nowrap rounded-xl px-4 py-2.5 text-xs font-semibold', status === item.id ? 'bg-primary text-primary-foreground' : 'border border-border bg-card text-muted-foreground')}>{item.label}</button>)}</div><div className="grid gap-5 lg:grid-cols-[1fr_300px]"><div className="relative min-h-[520px] overflow-hidden rounded-[2rem] border border-border bg-[#e4eadf] shadow-sm"><div className="absolute inset-0 opacity-40 civic-grid" /><svg className="absolute inset-0 h-full w-full" viewBox="0 0 1000 650" preserveAspectRatio="none"><path d="M70 520 C170 470 180 360 300 330 C420 295 430 185 555 190 C710 197 700 88 865 110 L900 540 Z" fill="#d5e1d3" stroke="#b6cbb4" strokeWidth="3" /><path d="M85 480 C260 420 270 335 420 300 S635 210 875 150 M115 570 C300 490 480 520 610 390 S760 260 920 250" fill="none" stroke="#c1d3c0" strokeWidth="12" strokeLinecap="round" /><path d="M60 360 C230 390 340 405 470 320 S710 160 940 190" fill="none" stroke="#cbd9c7" strokeWidth="5" /></svg><div className="absolute right-4 top-4 rounded-xl border border-border/70 bg-card/90 px-3 py-2 text-xs font-semibold text-primary shadow-sm"><MapPinned className="ml-1 inline size-3.5" />الكويت</div>{reports.map((r, i) => <button data-testid={`button-map-marker-${r.id}`} key={r.id} onClick={() => setSelected(r)} style={positions(r, i)} className="absolute flex size-9 -translate-x-1/2 -translate-y-1/2 items-center justify-center rounded-full border-[3px] border-card bg-accent text-accent-foreground shadow-md transition-transform hover:scale-125"><span className="font-mono-civic text-[10px]">{i + 1}</span></button>)}{reportsQuery.isLoading && <div className="absolute inset-0 flex items-center justify-center bg-card/40 backdrop-blur-sm"><Loader2 className="size-6 animate-spin text-primary" /></div>}{!reportsQuery.isLoading && reports.length === 0 && <div className="absolute inset-0 flex items-center justify-center"><div className="rounded-2xl bg-card/90 px-6 py-5 text-center shadow-md"><MapPinned className="mx-auto mb-2 size-6 text-muted-foreground" /><p className="text-sm font-semibold">لا توجد بلاغات هنا بعد</p></div></div>}<div className="absolute bottom-4 right-4 flex gap-2"><button data-testid="button-map-zoom-in" className="rounded-lg border border-border bg-card p-2 shadow-sm"><Plus className="size-4" /></button><button data-testid="button-map-zoom-out" className="rounded-lg border border-border bg-card p-2 shadow-sm"><Minus className="size-4" /></button></div></div><aside className="rounded-3xl border border-border bg-card p-5"><div className="flex items-center justify-between"><h3 className="font-semibold">في محيطك</h3><span className="font-mono-civic text-xs text-muted-foreground">{reports.length} بلاغ</span></div><div className="mt-5 space-y-1">{reports.slice(0, 5).map((r) => <button data-testid={`button-map-list-${r.id}`} key={r.id} onClick={() => setSelected(r)} className="flex w-full items-start gap-3 rounded-xl p-3 text-right hover:bg-muted"><span className="mt-1 flex size-7 shrink-0 items-center justify-center rounded-lg bg-secondary text-xs font-bold text-primary">{String(r.id).slice(-2)}</span><span className="min-w-0"><span className="block truncate text-sm font-semibold">{r.title}</span><span className="mt-1 block truncate text-xs text-muted-foreground">{r.locationName}</span></span></button>)}{reports.length === 0 && <p className="py-8 text-center text-sm text-muted-foreground">ستظهر البلاغات هنا عند مشاركتها.</p>}</div><Link href="/report/new" data-testid="link-map-add" className="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-primary py-3 text-sm font-semibold text-primary-foreground"><Plus className="size-4" />أضف ملاحظة للمكان</Link></aside></div>{selected && <ReportModal report={selected} close={() => setSelected(null)} support={(id) => support.mutate({ id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListReportsQueryKey() }); setSelected(null); } })} />}</PageFrame>;
}

function NewReportPage() {
  const [, setLocation] = useLocation(); const [step, setStep] = useState(1); const [done, setDone] = useState(false); const [image, setImage] = useState(''); const [uploadError, setUploadError] = useState(''); const [locationLoading, setLocationLoading] = useState(false); const [locationError, setLocationError] = useState(''); const [form, setForm] = useState<ReportInput>({ image: '', title: '', description: '', category: '', latitude: 29.3759, longitude: 47.9774, locationName: '' }); const catsQuery = useListCategories(); const cats: Category[] = (catsQuery.data || fallbackCategories).map((cat) => ({ ...cat, name: cat.id })); const create = useCreateReport(); const upload = useRequestUploadUrl();
  const update = (key: keyof ReportInput, value: string | number) => setForm((prev) => ({ ...prev, [key]: value }));
  const handleImage = async (file?: File) => { if (!file) return; setUploadError(''); if (!file.type.startsWith('image/') || file.size > 8_000_000) { setUploadError('اختر صورة بصيغة صحيحة وحجم أقل من 8 ميجابايت.'); return; } const reader = new FileReader(); reader.onload = () => setImage(String(reader.result)); reader.readAsDataURL(file); try { const signed = await upload.mutateAsync({ data: { name: file.name, size: file.size, contentType: file.type } }); const uploaded = await fetch(signed.uploadURL, { method: 'PUT', headers: { 'Content-Type': file.type }, body: file }); if (!uploaded.ok) throw new Error('upload_failed'); update('image', signed.objectPath); } catch { setUploadError('تعذر رفع الصورة. حاول مرة أخرى.'); update('image', ''); } };
  const useCurrentLocation = () => { if (!navigator.geolocation) { setLocationError('المتصفح لا يدعم تحديد الموقع. اكتب اسم المكان بدلًا من ذلك.'); return; } setLocationError(''); setLocationLoading(true); navigator.geolocation.getCurrentPosition((position) => { update('latitude', position.coords.latitude); update('longitude', position.coords.longitude); update('locationName', 'موقعي الحالي'); setLocationLoading(false); }, () => { setLocationLoading(false); setLocationError('لم نتمكن من الوصول لموقعك. اسمح بالوصول أو اكتب اسم المكان يدويًا.'); }, { enableHighAccuracy: true, timeout: 10000 }); };
  const next = () => { if (step === 1 && (!form.category || !form.title || !form.description || !form.image || upload.isPending)) return; if (step === 2 && !form.locationName) return; if (step < 3) setStep(step + 1); else create.mutate({ data: form }, { onSuccess: () => setDone(true) }); };
  if (done) return <PageFrame title="وصل البلاغ" description="شكراً لأنك أخذت خطوة تخلي الكويت أجمل."><div className="mx-auto max-w-xl rounded-[2rem] border border-border bg-card p-8 text-center shadow-sm sm:p-12"><div className="mx-auto flex size-16 items-center justify-center rounded-2xl bg-secondary text-primary"><Check className="size-8" /></div><h2 className="mt-6 text-2xl font-bold">تم استلام بلاغك</h2><p className="mt-3 leading-7 text-muted-foreground">راح يمر على فريقنا للمراجعة، وتقدر تتابع حالته من البلاغات أو مساحتك.</p><div className="mt-7 flex flex-wrap justify-center gap-3"><Link href="/reports" data-testid="link-success-reports" className="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground">تصفح البلاغات</Link><Link href="/dashboard" data-testid="link-success-dashboard" className="rounded-xl border border-border px-5 py-3 text-sm font-semibold">روح لمساحتي</Link></div></div></PageFrame>;
  const labels = ['تفاصيل الملاحظة', 'الموقع', 'مراجعة وإرسال'];
  return <PageFrame eyebrow="مساهمة جديدة" title="خلّنا نسمعك" description="ملاحظتك عن المكان تساعدنا نعرف أين نبدأ."><div className="mx-auto max-w-3xl"><div className="mb-8 flex items-center justify-between">{labels.map((label, i) => <div key={label} className={cn('flex items-center gap-2 text-xs font-semibold', i + 1 <= step ? 'text-primary' : 'text-muted-foreground')}><span className={cn('flex size-8 items-center justify-center rounded-full font-mono-civic', i + 1 < step ? 'bg-secondary text-primary' : i + 1 === step ? 'bg-primary text-primary-foreground' : 'bg-muted')}>{i + 1 < step ? <Check className="size-4" /> : i + 1}</span><span className="hidden sm:block">{label}</span>{i < 2 && <span className="mx-1 hidden h-px w-10 bg-border sm:block md:w-28" />}</div>)}</div><div className="rounded-[2rem] border border-border bg-card p-5 shadow-sm sm:p-8">{step === 1 && <div className="animate-fade"><div className="mb-6"><h2 className="text-xl font-bold">وش اللي لاحظته؟</h2><p className="mt-1 text-sm text-muted-foreground">اختَر التصنيف الأقرب، واكتب لنا الصورة كاملة.</p></div><label className="mb-2 block text-sm font-semibold">التصنيف</label><div className="grid grid-cols-2 gap-3 sm:grid-cols-4">{cats.map((cat) => <button data-testid={`button-select-category-${cat.id}`} key={cat.id} onClick={() => update('category', cat.name)} className={cn('rounded-2xl border p-4 text-right transition-all', form.category === cat.name ? 'border-primary bg-primary/5 ring-1 ring-primary' : 'border-border hover:border-primary/40')}><span className="font-mono-civic text-sm text-accent">{cat.icon}</span><span className="mt-3 block text-sm font-semibold">{cat.label}</span></button>)}</div><label className="mt-7 block text-sm font-semibold">عنوان مختصر</label><input data-testid="input-report-title" value={form.title} onChange={(e) => update('title', e.target.value)} placeholder="مثلاً: إنارة لا تعمل أمام الحديقة" className="mt-2 h-12 w-full rounded-xl border border-input bg-background px-4 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" /><label className="mt-5 block text-sm font-semibold">وصف الملاحظة</label><textarea data-testid="input-report-description" value={form.description} onChange={(e) => update('description', e.target.value)} placeholder="اشرح لنا وش صار ومتى لاحظته..." rows={5} className="mt-2 w-full resize-none rounded-xl border border-input bg-background p-4 text-sm leading-7 outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" /><label className="mt-5 block text-sm font-semibold">صورة المكان <span className="font-normal text-muted-foreground">(مطلوبة)</span></label><label data-testid="input-report-image" className="mt-2 flex min-h-28 cursor-pointer items-center justify-center gap-3 rounded-xl border border-dashed border-primary/30 bg-muted/40 text-sm text-muted-foreground hover:bg-muted">{image ? <img src={image} alt="معاينة" className="h-24 w-full rounded-lg object-cover" /> : <><Upload className="size-5" />اضغط لإرفاق صورة<input type="file" accept="image/*" className="hidden" onChange={(e) => handleImage(e.target.files?.[0])} /></>}{upload.isPending && <Loader2 className="size-4 animate-spin" />}</label>{uploadError && <p className="mt-2 text-sm text-accent">{uploadError}</p>}</div>}{step === 2 && <div className="animate-fade"><h2 className="text-xl font-bold">وين المكان؟</h2><p className="mt-1 text-sm text-muted-foreground">حدد مكانك تلقائيًا أو اكتب اسم الشارع والمنطقة فقط.</p><div className="mt-6 flex flex-wrap gap-3"><button type="button" data-testid="button-use-current-location" onClick={useCurrentLocation} disabled={locationLoading} className="flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground disabled:opacity-60">{locationLoading ? <Loader2 className="size-4 animate-spin" /> : <MapPinned className="size-4" />}استخدم موقعي الحالي</button><span className="flex items-center text-xs text-muted-foreground">أو اكتب المكان يدويًا</span></div><label className="mt-7 block text-sm font-semibold">وين صاير؟</label><input data-testid="input-report-location" value={form.locationName} onChange={(e) => update('locationName', e.target.value)} placeholder="مثلاً: شارع الخليج، السالمية" className="mt-2 h-12 w-full rounded-xl border border-input bg-background px-4 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/10" />{locationError && <p className="mt-2 text-sm text-accent">{locationError}</p>}<div className="mt-6 flex items-start gap-3 rounded-2xl border border-border bg-muted/50 p-4 text-sm text-muted-foreground"><MapPinned className="mt-0.5 size-5 shrink-0 text-accent" /><p>{form.locationName ? `الموقع المحدد: ${form.locationName}` : 'ما يحتاج تدخل خطوط الطول والعرض. يكفي اختيار موقعك أو كتابة اسم المكان.'}</p></div></div>}{step === 3 && <div className="animate-fade"><h2 className="text-xl font-bold">راجع بلاغك</h2><p className="mt-1 text-sm text-muted-foreground">تأكد من التفاصيل قبل الإرسال.</p><div className="mt-6 overflow-hidden rounded-2xl border border-border">{image && <img src={image} alt="" className="h-44 w-full object-cover" />}<div className="space-y-4 p-5"><div><div className="text-xs text-muted-foreground">التصنيف</div><div className="mt-1 font-semibold">{cats.find((c) => c.name === form.category)?.label || form.category}</div></div><div><div className="text-xs text-muted-foreground">العنوان</div><div className="mt-1 font-semibold">{form.title}</div></div><div><div className="text-xs text-muted-foreground">الموقع</div><div className="mt-1 font-semibold">{form.locationName}</div></div><p className="border-t border-border pt-4 text-sm leading-7 text-muted-foreground">{form.description}</p></div></div></div>}<div className="mt-8 flex items-center justify-between border-t border-border pt-5"><button data-testid="button-report-back" onClick={() => step > 1 ? setStep(step - 1) : setLocation('/reports')} className="flex items-center gap-2 rounded-xl px-4 py-2.5 text-sm font-semibold text-muted-foreground hover:bg-muted"><ArrowRightIcon />رجوع</button><button data-testid="button-report-next" onClick={next} disabled={create.isPending || upload.isPending} className="flex items-center gap-2 rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-primary-foreground disabled:opacity-60">{create.isPending || upload.isPending ? <Loader2 className="size-4 animate-spin" /> : step === 3 ? <Send className="size-4" /> : <ArrowLeft className="size-4" />}{step === 3 ? 'إرسال البلاغ' : 'التالي'}</button></div>{create.isError && <p className="mt-4 text-center text-sm text-accent">تعذر إرسال البلاغ. تأكد من تسجيل الدخول ثم حاول مرة ثانية.</p>}</div></div></PageFrame>;
}
function ArrowRightIcon() { return <ArrowLeft className="size-4 rotate-180" />; }

function DashboardPage() {
  const query = useGetDashboard(); const data = query.data; const [selected, setSelected] = useState<Report | null>(null); const support = useSupportReport(); const qc = useQueryClient();
  if (query.isLoading) return <PageFrame title="مساحتي" description="كل مساهماتك في مكان واحد."><AsyncState type="loading" /></PageFrame>;
  if (query.isError || !data) return <PageFrame title="مساحتي" description="كل مساهماتك في مكان واحد."><AsyncState type="error" retry={() => query.refetch()} /></PageFrame>;
  const progress = Math.min(100, Math.round((data.points / Math.max(1, data.nextLevelPoints)) * 100));
  return <PageFrame eyebrow="مساحتي" title={`هلا ${data.name}`} description="هذا أثر ملاحظاتك على المكان حولك."><div className="grid gap-5 lg:grid-cols-[1fr_330px]"><div className="space-y-5"><div className="rounded-[2rem] bg-primary p-6 text-primary-foreground shadow-md sm:p-8"><div className="flex items-start justify-between"><div><p className="text-sm text-primary-foreground/65">رصيدك الحالي</p><div data-testid="text-dashboard-points" className="mt-2 font-mono-civic text-5xl font-bold text-secondary">{data.points}</div><p className="mt-2 text-xs text-primary-foreground/65">نقطة مجتمعية</p></div><div className="flex size-14 items-center justify-center rounded-2xl bg-secondary text-xl font-bold text-primary">{data.initials}</div></div><div className="mt-8 flex items-center justify-between text-xs"><span>المستوى: <strong className="text-secondary">{data.level}</strong></span><span>{data.nextLevelPoints - data.points > 0 ? `باقي ${data.nextLevelPoints - data.points} نقطة` : 'وصلت للمستوى التالي'}</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-primary-foreground/15"><div className="h-full rounded-full bg-secondary transition-all" style={{ width: `${progress}%` }} /></div></div><div className="grid grid-cols-2 gap-3 sm:grid-cols-4"><StatChip value={data.reportsCount} label="بلاغاتي" /><StatChip value={data.resolvedCount} label="تم حلّه" accent /><StatChip value={`${data.contributionRate}%`} label="معدل الأثر" /><StatChip value={data.notifications.length} label="تنبيهات" /></div><div className="rounded-3xl border border-border bg-card p-5 sm:p-6"><div className="mb-5 flex items-center justify-between"><h2 className="font-bold">بلاغاتي</h2><Link href="/report/new" data-testid="link-dashboard-add" className="flex items-center gap-1 text-xs font-semibold text-accent"><Plus className="size-4" />بلاغ جديد</Link></div>{data.reports.length === 0 ? <AsyncState type="empty" /> : <div className="space-y-2">{data.reports.map((r) => <button data-testid={`button-dashboard-report-${r.id}`} key={r.id} onClick={() => setSelected(r)} className="flex w-full items-center gap-3 rounded-2xl border border-transparent p-3 text-right hover:border-border hover:bg-muted"><div className="flex size-11 shrink-0 items-center justify-center rounded-xl bg-secondary/45 text-primary"><FileText className="size-5" /></div><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold">{r.title}</div><div className="mt-1 text-xs text-muted-foreground">{r.locationName} · {fmtDate(r.createdAt)}</div></div><span className={cn('flex shrink-0 items-center gap-1 rounded-full px-2 py-1 text-[10px] font-semibold', statusTone(r.status))}>{statusIcon(r.status)}{r.statusLabel}</span></button>)}</div>}</div></div><aside className="space-y-5"><div className="rounded-3xl border border-border bg-card p-5"><div className="flex items-center justify-between"><h2 className="font-bold">آخر التنبيهات</h2><Bell className="size-4 text-accent" /></div><div className="mt-4 space-y-1">{data.notifications.length === 0 ? <p className="py-6 text-sm text-muted-foreground">ما عندك تنبيهات جديدة.</p> : data.notifications.map((n) => <div data-testid={`notification-${n.id}`} key={n.id} className={cn('rounded-2xl p-3', n.read ? '' : 'bg-secondary/20')}><div className="flex gap-2"><span className="mt-1 size-2 shrink-0 rounded-full bg-accent" /><div><p className="text-sm font-semibold">{n.title}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{n.body}</p><p className="mt-2 text-[10px] text-muted-foreground">{fmtDate(n.createdAt)}</p></div></div></div>)}</div></div><div className="rounded-3xl border border-secondary/40 bg-secondary/20 p-5"><Target className="size-5 text-primary" /><h3 className="mt-4 font-bold">كل خطوة محسوبة</h3><p className="mt-2 text-sm leading-6 text-primary/70">صورة، وصف، أو دعم لبلاغ قريب منك. مشاركتك تخلي التغيير أوضح وأسرع.</p></div></aside></div>{selected && <ReportModal report={selected} close={() => setSelected(null)} support={(id) => support.mutate({ id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetDashboardQueryKey() }); setSelected(null); } })} />}</PageFrame>;
}

function AdminPage() {
  const overview = useGetAdminOverview(); const reports = useListReports({ sort: 'latest' }); const [statusFilter, setStatusFilter] = useState('all'); const update = useUpdateReport(); const qc = useQueryClient(); const data = overview.data as AdminOverview | undefined; const rows = (reports.data || []).filter((r) => statusFilter === 'all' || r.status === statusFilter);
  const setStatus = (id: number, status: 'received' | 'reviewing' | 'referred' | 'resolved' | 'closed') => update.mutate({ id, data: { status } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListReportsQueryKey({ sort: 'latest' }) }); qc.invalidateQueries({ queryKey: getGetAdminOverviewQueryKey() }); } });
  if (overview.isLoading) return <PageFrame eyebrow="لوحة الإدارة" title="صورة المدينة" description="مؤشرات البلاغات والمناطق النشطة."><AsyncState type="loading" /></PageFrame>;
  if (overview.isError || !data) return <PageFrame eyebrow="لوحة الإدارة" title="صورة المدينة" description="مؤشرات البلاغات والمناطق النشطة."><div className="rounded-3xl border border-border bg-card px-6 py-12 text-center"><ShieldCheck className="mx-auto mb-3 size-8 text-accent" /><h3 className="font-semibold">تحتاج صلاحية الإدارة</h3><p className="mt-2 text-sm text-muted-foreground">سجّل الدخول بحساب الإدارة حتى تفتح هذه الصفحة.</p><Link href="/login" className="mt-5 inline-flex rounded-xl bg-primary px-4 py-2.5 text-sm font-semibold text-primary-foreground">تسجيل الدخول</Link></div></PageFrame>;
  return <PageFrame eyebrow="لوحة الإدارة" title="صورة المدينة" description="إدارة البلاغات ومتابعة سرعة الاستجابة من مكان واحد."><div className="grid gap-3 sm:grid-cols-3 lg:grid-cols-6"><StatChip value={data.totalReports} label="إجمالي البلاغات" /><StatChip value={data.newReports} label="جديدة" accent /><StatChip value={data.reviewingReports} label="قيد المراجعة" /><StatChip value={data.resolvedReports} label="تم حلّه" accent /><StatChip value={data.usersCount} label="مستخدمون" /><StatChip value={data.totalPoints} label="إجمالي النقاط" /></div><div className="mt-5 grid gap-5 lg:grid-cols-[1fr_320px]"><div className="rounded-3xl border border-border bg-card p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><h2 className="font-bold">طابور البلاغات</h2><div className="flex gap-1 overflow-auto">{statuses.map((s) => <button data-testid={`button-admin-filter-${s.id}`} key={s.id} onClick={() => setStatusFilter(s.id)} className={cn('whitespace-nowrap rounded-lg px-3 py-1.5 text-[11px]', statusFilter === s.id ? 'bg-primary text-primary-foreground' : 'bg-muted text-muted-foreground')}>{s.label}</button>)}</div></div><div className="mt-5 overflow-x-auto"><table className="w-full min-w-[650px] text-right text-sm"><thead className="border-b border-border text-xs text-muted-foreground"><tr><th className="pb-3 font-medium">البلاغ</th><th className="pb-3 font-medium">التصنيف</th><th className="pb-3 font-medium">الحالة</th><th className="pb-3 font-medium">الإجراء</th></tr></thead><tbody>{rows.map((r) => <tr data-testid={`row-admin-report-${r.id}`} key={r.id} className="border-b border-border/60 last:border-0"><td className="py-4"><div className="font-semibold">{r.title}</div><div className="mt-1 text-xs text-muted-foreground">{r.locationName} · #{r.id}</div></td><td className="py-4 text-xs text-muted-foreground">{r.categoryLabel}</td><td className="py-4"><span className={cn('rounded-full px-2.5 py-1 text-[10px] font-semibold', statusTone(r.status))}>{r.statusLabel}</span></td><td className="py-4"><select data-testid={`select-admin-status-${r.id}`} value={r.status} disabled={update.isPending} onChange={(e) => setStatus(r.id, e.target.value as 'received' | 'reviewing' | 'referred' | 'resolved' | 'closed')} className="rounded-lg border border-input bg-background px-2 py-1.5 text-xs"><option value="received">استلمناها</option><option value="reviewing">قيد المراجعة</option><option value="referred">أُحيلت</option><option value="resolved">تم الحل</option><option value="closed">مغلقة</option></select></td></tr>)}</tbody></table>{rows.length === 0 && <p className="py-12 text-center text-sm text-muted-foreground">لا توجد بلاغات بهذا الفلتر.</p>}</div></div><aside className="space-y-5"><div className="rounded-3xl border border-border bg-card p-5"><h2 className="font-bold">حسب التصنيف</h2><div className="mt-5 space-y-4">{data.byCategory.map((item, i) => <div data-testid={`admin-category-${i}`} key={item.label}><div className="mb-2 flex justify-between text-xs"><span>{item.label}</span><span className="font-mono-civic text-muted-foreground">{item.value}</span></div><div className="h-2 rounded-full bg-muted"><div className={cn('h-full rounded-full', i % 3 === 0 ? 'bg-primary' : i % 3 === 1 ? 'bg-secondary' : 'bg-accent')} style={{ width: `${Math.min(100, (item.value / Math.max(1, data.totalReports)) * 100)}%` }} /></div></div>)}</div></div><div className="rounded-3xl border border-border bg-primary p-5 text-primary-foreground"><UsersRound className="size-5 text-secondary" /><div className="mt-4 text-3xl font-bold font-mono-civic">{data.usersCount}</div><p className="mt-1 text-xs text-primary-foreground/65">شخص يساهم في تحسين الكويت</p></div></aside></div></PageFrame>;
}

function LoginPage() {
  const [, setLocation] = useLocation();
  const [register, setRegister] = useState(false);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [pending, setPending] = useState(false);
  const submit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');
    setPending(true);
    try {
      const response = await fetch(`/api/auth/${register ? 'register' : 'login'}`, {
        method: 'POST',
        credentials: 'include',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(register ? { name, email, password } : { email, password }),
      });
      const body = await response.json();
      if (!response.ok) throw new Error(body.error || 'تعذر إكمال العملية.');
      setLocation(body.isAdmin ? '/admin' : '/dashboard');
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : 'تعذر إكمال العملية.');
    } finally {
      setPending(false);
    }
  };
  return <div className="min-h-[100dvh] bg-primary"><div className="mx-auto grid min-h-[100dvh] max-w-[1440px] lg:grid-cols-[.9fr_1.1fr]"><div className="relative hidden overflow-hidden p-12 text-primary-foreground lg:flex lg:flex-col lg:justify-between"><div className="absolute inset-0 civic-grid opacity-10" /><div className="relative"><Link href="/" data-testid="link-login-brand"><img src={logo} alt="نجمّلها" className="h-16 w-28 rounded-xl object-cover mix-blend-screen" /></Link><p className="mt-10 max-w-md text-5xl font-bold leading-[1.25]">المكان لنا،<br /><span className="text-secondary">والأثر باسمك.</span></p></div><div className="relative flex items-center gap-3 text-sm text-primary-foreground/60"><ShieldCheck className="size-5 text-secondary" />حسابك محفوظ وتقدر تدخل من أي جهاز</div></div><div className="flex items-center justify-center bg-background p-5 sm:p-10"><div className="w-full max-w-md animate-rise"><Link href="/" data-testid="link-login-back" className="mb-10 flex items-center gap-2 text-sm text-muted-foreground"><ArrowRightIcon />العودة للرئيسية</Link><div className="mb-8"><div className="mb-4 flex size-12 items-center justify-center rounded-2xl bg-secondary text-primary"><LockKeyhole className="size-5" /></div><h1 className="text-3xl font-bold">{register ? 'أنشئ مساحتك' : 'حياك في نجمّلها'}</h1><p className="mt-2 text-sm leading-7 text-muted-foreground">{register ? 'سجّل عشان تتابع أثر مساهماتك وتجمع نقاطك.' : 'سجّل دخولك وتابع كيف تتحول الملاحظة إلى تغيير.'}</p></div><form onSubmit={submit} className="space-y-4">{register && <label className="block text-sm font-semibold">الاسم<input data-testid="input-login-name" required minLength={2} autoComplete="name" value={name} onChange={(e) => setName(e.target.value)} placeholder="اسمك الأول" className="mt-2 h-12 w-full rounded-xl border border-input bg-card px-4 text-sm outline-none focus:border-primary" /></label>}<label className="block text-sm font-semibold">البريد الإلكتروني<input data-testid="input-login-email" required type="email" autoComplete="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder="name@example.com" className="mt-2 h-12 w-full rounded-xl border border-input bg-card px-4 text-sm outline-none focus:border-primary" /></label><label className="block text-sm font-semibold">كلمة المرور<input data-testid="input-login-password" required minLength={register ? 8 : 1} autoComplete={register ? 'new-password' : 'current-password'} type="password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="••••••••" className="mt-2 h-12 w-full rounded-xl border border-input bg-card px-4 text-sm outline-none focus:border-primary" /></label><button data-testid="button-login-submit" disabled={pending} className="flex h-12 w-full items-center justify-center gap-2 rounded-xl bg-primary text-sm font-semibold text-primary-foreground hover:opacity-90 disabled:opacity-60">{pending ? <Loader2 className="size-4 animate-spin" /> : <ArrowLeft className="size-4" />}{register ? 'إنشاء الحساب' : 'تسجيل الدخول'}</button></form>{error && <p className="mt-4 rounded-xl bg-accent/10 px-4 py-3 text-sm text-accent">{error}</p>}<button data-testid="button-toggle-register" onClick={() => { setRegister(!register); setError(''); }} className="mt-6 w-full text-center text-sm text-muted-foreground hover:text-primary">{register ? 'عندي حساب، أريد تسجيل الدخول' : 'جديد هنا؟ أنشئ حساباً الآن'}</button><p className="mt-10 text-center text-[11px] leading-5 text-muted-foreground">كلمة المرور مشفّرة، ولا تظهر لأي مستخدم آخر.</p></div></div></div></div>;
}

function PageFrame({ eyebrow, title, description, children }: { eyebrow?: string; title: string; description?: string; children: ReactNode }) {
  return <div className="mx-auto max-w-[1440px] px-4 py-10 sm:px-8 sm:py-14"><div className="mb-9 max-w-2xl animate-rise">{eyebrow && <div className="mb-3 text-xs font-bold tracking-wide text-accent">{eyebrow}</div>}<h1 className="display-ar text-4xl font-bold leading-tight sm:text-5xl">{title}</h1>{description && <p className="mt-3 text-sm leading-7 text-muted-foreground sm:text-base">{description}</p>}</div>{children}</div>;
}

function Router() {
  const [location] = useLocation();
  return <ErrorBoundary resetKey={location}><Switch><Route path="/" component={HomePage} /><Route path="/reports" component={ReportsPage} /><Route path="/report/new" component={NewReportPage} /><Route path="/dashboard" component={DashboardPage} /><Route path="/admin" component={AdminPage} /><Route path="/login" component={LoginPage} /><Route component={() => <PageFrame title="الصفحة غير موجودة" description="الرابط الذي تبحث عنه غير متاح."><Link href="/" data-testid="link-not-found-home" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-3 text-sm font-semibold text-primary-foreground">العودة للرئيسية <ArrowLeft className="size-4" /></Link></PageFrame>} /></Switch></ErrorBoundary>;
}

function AppContent() {
  const [location] = useLocation();
  return location === '/login' ? <Router /> : <Shell><Router /></Shell>;
}

function App() {
  return <QueryClientProvider client={queryClient}><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><AppContent /></WouterRouter><Toaster /></QueryClientProvider>;
}

export default App;